<?php use yii\widgets\ActiveForm;use yii\helpers\{Html,ArrayHelper};use common\models\NewsCategory;$this->title=$model->isNewRecord?'Новая новость':'Редактирование новости';?><div class="card p-4"><?php $f=ActiveForm::begin();echo $f->field($model,'title');echo $f->field($model,'slug');echo $f->field($model,'category_id')->dropDownList(ArrayHelper::map(NewsCategory::find()->all(),'id','name'),['prompt'=>'Без категории']);echo $f->field($model,'excerpt')->textarea(['rows'=>3]);echo $f->field($model,'body')->textarea(['rows'=>14]);echo $f->field($model,'published')->checkbox();echo $f->field($model,'published_at')->textInput(['placeholder'=>'YYYY-MM-DD HH:MM:SS']);echo Html::submitButton('Сохранить',['class'=>'btn btn-primary']);ActiveForm::end();?></div>